SELECT jsonb_build_object('receipt_id',d.id,'request_key',d.request_key,'node_id',n.id,'file_name',n.name,'bucket',n.storage_bucket,'path',n.storage_path,'sha256',n.sha256_checksum,'bytes',n.file_size_bytes,'revision_id',r.id,'revision',r.version,'register_id',c.id,'document_number',c.document_number,'status',c.document_status,'audit_id',a.id,'actor',a.actor_user_id,'source_revision_matches',c.source_revision_id=r.id,'receipt_links_match',d.generated_drive_node_id=n.id AND d.generated_revision_id=r.id AND d.document_control_register_id=c.id AND d.audit_event_id=a.id,'owned_attempt_consumed',s.consumed_by_receipt_id=d.id AND s.uploaded_by=d.created_by,'physical_storage_metadata_exists',o.id IS NOT NULL,'bucket_is_private',NOT b.public,'hashes_match',d.sha256_checksum=n.sha256_checksum AND r.sha256_checksum=n.sha256_checksum AND s.sha256_checksum=n.sha256_checksum,'auth_users',(SELECT count(*) FROM auth.users)) AS proof FROM public.project_lifecycle_document_drafts d JOIN public.drive_nodes n ON n.id=d.generated_drive_node_id JOIN public.drive_node_revisions r ON r.id=d.generated_revision_id JOIN public.document_control_registers c ON c.id=d.document_control_register_id JOIN public.activity_log a ON a.id=d.audit_event_id JOIN public.lifecycle_document_storage_attempts s ON s.consumed_by_receipt_id=d.id LEFT JOIN storage.objects o ON o.bucket_id=d.storage_bucket AND o.name=d.storage_path JOIN storage.buckets b ON b.id=d.storage_bucket WHERE d.id='24fc81ad-e94a-4368-891c-c505051effe3';